import React, { useState, useRef, useEffect } from 'react';

const VideoEditing: React.FC = () => {
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  const [isPrivacyMode, setIsPrivacyMode] = useState(false);
  const [fps, setFps] = useState(0);
  const [statusMessage, setStatusMessage] = useState("Ready to start streaming");
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  const startWebcam = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsWebcamActive(true);
        setStatusMessage("Webcam started successfully");
      }
    } catch (err) {
      console.error(err);
      setStatusMessage("Failed to access webcam");
    }
  };

  const stopWebcam = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      setIsWebcamActive(false);
      setIsPrivacyMode(false);
      setStatusMessage("Stream stopped");
    }
  };

  const processFrame = () => {
    if (!videoRef.current || !canvasRef.current || !isWebcamActive) return;

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { videoWidth, videoHeight } = videoRef.current;
    if (videoWidth === 0) {
      requestRef.current = requestAnimationFrame(processFrame);
      return;
    }

    canvasRef.current.width = videoWidth;
    canvasRef.current.height = videoHeight;

    if (isPrivacyMode) {
      // Simulate background removal/masking
      // In a production app, we would use MediaPipe or BodyPix here
      ctx.filter = 'blur(15px)';
      ctx.drawImage(videoRef.current, 0, 0, videoWidth, videoHeight);
      ctx.filter = 'none';

      // Draw a "privacy shield" overlay or highlight the foreground
      ctx.fillStyle = 'rgba(15, 23, 42, 0.4)';
      ctx.fillRect(0, 0, videoWidth, videoHeight);

      ctx.fillStyle = 'white';
      ctx.font = 'bold 20px Inter';
      ctx.textAlign = 'center';
      ctx.fillText("PRIVACY MODE ACTIVE", videoWidth / 2, videoHeight / 2);
    } else {
      ctx.drawImage(videoRef.current, 0, 0, videoWidth, videoHeight);
    }

    setFps(Math.round(24 + Math.random() * 2)); // Simulated FPS
    requestRef.current = requestAnimationFrame(processFrame);
  };

  useEffect(() => {
    if (isWebcamActive) {
      requestRef.current = requestAnimationFrame(processFrame);
      setStatusMessage("Processing video frames...");
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [isWebcamActive, isPrivacyMode]);

