import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Landing from './pages/Landing';
import About from './pages/About';
import DocumentEnhancement from './pages/DocumentEnhancement';
import HomeStaging from './pages/HomeStaging';
import VideoEditing from './pages/VideoEditing';
import Auth from './pages/Auth';
import { User } from './types';

const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState('/');
  const [user, setUser] = useState<User | null>(null);

  // Sync hash with path
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '') || '/';
      setCurrentPath(hash);
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (path: string) => {
    window.location.hash = path;
    setCurrentPath(path);
    window.scrollTo(0, 0);
  };

  const renderPage = () => {
    switch (currentPath) {
      case '/': return <Landing onNavigate={navigate} />;
      case '/docs': return <DocumentEnhancement />;
      case '/staging': return <HomeStaging />;
      case '/video': return <VideoEditing />;
      case '/about': return <About />;
      case '/signin': return (
        <Auth 
          type="SIGNIN" 
          onAuthSuccess={(u) => { setUser(u); navigate('/'); }} 
          onSwitch={() => navigate('/signup')} 
        />
      );
      case '/signup': return (
        <Auth 
          type="SIGNUP" 
          onAuthSuccess={(u) => { setUser(u); navigate('/'); }} 
          onSwitch={() => navigate('/signin')} 
        />
      );
      default: return <Landing onNavigate={navigate} />;
    }
  };

  return (
    <Layout 
      activePath={currentPath} 
      onNavigate={navigate}
      user={user}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

