import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Landing from './pages/Landing';
import About from './pages/About';
import DocumentEnhancement from './pages/DocumentEnhancement';
import HomeStaging from './pages/HomeStaging';
import VideoEditing from './pages/VideoEditing';
import Auth from './pages/Auth';
import { User, UserTier } from './types';

const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState('/');
  const [user, setUser] = useState<User | null>(null);

  // Sync hash with path
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '') || '/';
      setCurrentPath(hash);
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (path: string) => {
    window.location.hash = path;
    setCurrentPath(path);
    window.scrollTo(0, 0);
  };

  const renderPage = () => {
    const userTier = user?.tier || UserTier.FREE;

    switch (currentPath) {
      case '/': return <Landing onNavigate={navigate} />;
      case '/docs': return <DocumentEnhancement userTier={userTier} />;
      case '/staging': return <HomeStaging userTier={userTier} />;
      case '/video': return <VideoEditing />;
      case '/about': return <About />;
      case '/signin': return (
        <Auth 
          type="SIGNIN" 
          onAuthSuccess={(u) => { setUser(u); navigate('/'); }} 
          onSwitch={() => navigate('/signup')} 
        />
      );
      case '/signup': return (
        <Auth 
          type="SIGNUP" 
          onAuthSuccess={(u) => { setUser(u); navigate('/'); }} 
          onSwitch={() => navigate('/signin')} 
        />
      );
      default: return <Landing onNavigate={navigate} />;
    }
  };

  return (
    <Layout 
      activePath={currentPath} 
      onNavigate={navigate}
      user={user}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";

// Initialize AI client using the API key from environment variables
const getAIClient = () => {
  // Use the process.env.API_KEY string directly as per guidelines
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const enhanceDocument = async (base64Image: string): Promise<string> => {
  const ai = getAIClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
          { text: "Enhance this scanned document. Remove shadows, human fingers, background noise, and improve contrast to make it perfectly readable like a professional scan." }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image part returned from Gemini");
  } catch (error) {
    console.error("Gemini Document Enhancement Error:", error);
    throw error;
  }
};

export const stageRoom = async (base64Image: string, instructions: string = ""): Promise<string> => {
  const ai = getAIClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
          { text: `Act as a professional interior stager. Remove all existing furniture, clutter, and distracting objects from this room to visualize a clean, empty, or minimally staged professional space. ${instructions}` }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
