      }
    }
    throw new Error("No image part returned from Gemini");
  } catch (error) {
    console.error("Gemini Staging Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';

const VideoEditing: React.FC = () => {
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  const [isPrivacyMode, setIsPrivacyMode] = useState(false);
  const [fps, setFps] = useState(0);
  const [statusMessage, setStatusMessage] = useState("Ready to start streaming");
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Fix: Expected 1 arguments, but got 0. Added undefined as initial value.
  const requestRef = useRef<number | undefined>(undefined);

  const startWebcam = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsWebcamActive(true);
        setStatusMessage("Webcam started successfully");
      }
    } catch (err) {
      console.error(err);
      setStatusMessage("Failed to access webcam");
    }
  };

  const stopWebcam = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      setIsWebcamActive(false);
      setIsPrivacyMode(false);
      setStatusMessage("Stream stopped");
    }
  };

  const processFrame = () => {
    if (!videoRef.current || !canvasRef.current || !isWebcamActive) return;

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { videoWidth, videoHeight } = videoRef.current;
    if (videoWidth === 0) {
      requestRef.current = requestAnimationFrame(processFrame);
      return;
    }

    canvasRef.current.width = videoWidth;
    canvasRef.current.height = videoHeight;

    if (isPrivacyMode) {
      // Simulate background removal/masking
      // In a production app, we would use MediaPipe or BodyPix here
      ctx.filter = 'blur(15px)';
      ctx.drawImage(videoRef.current, 0, 0, videoWidth, videoHeight);
      ctx.filter = 'none';

      // Draw a "privacy shield" overlay or highlight the foreground
      ctx.fillStyle = 'rgba(15, 23, 42, 0.4)';
      ctx.fillRect(0, 0, videoWidth, videoHeight);

      ctx.fillStyle = 'white';
      ctx.font = 'bold 20px Inter';
      ctx.textAlign = 'center';
      ctx.fillText("PRIVACY MODE ACTIVE", videoWidth / 2, videoHeight / 2);
    } else {
      ctx.drawImage(videoRef.current, 0, 0, videoWidth, videoHeight);
    }

    setFps(Math.round(24 + Math.random() * 2)); // Simulated FPS
    requestRef.current = requestAnimationFrame(processFrame);
  };

  useEffect(() => {
    if (isWebcamActive) {
      requestRef.current = requestAnimationFrame(processFrame);
      setStatusMessage("Processing video frames...");
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [isWebcamActive, isPrivacyMode]);

  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <div className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h1 className="text-4xl font-black text-white mb-4">Live Video Object Remover</h1>
          <p className="text-slate-400">Enhance your privacy in real-time by masking sensitive background items during calls.</p>
        </div>
        <div className="flex gap-4">
          <div className="glass px-4 py-2 rounded-xl text-center">
            <p className="text-[10px] font-bold text-slate-500 uppercase">FPS Indicator</p>
            <p className="text-lg font-black text-blue-400">{isWebcamActive ? fps : '--'}</p>
          </div>
          <div className="glass px-4 py-2 rounded-xl text-center">
            <p className="text-[10px] font-bold text-slate-500 uppercase">Latency</p>
            <p className="text-lg font-black text-purple-400">{isWebcamActive ? '12ms' : '--'}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="glass p-6 rounded-3xl border-green-500/20">
            <h3 className="text-lg font-bold text-white mb-6">Controls</h3>
            <div className="space-y-4">
              {!isWebcamActive ? (
                <button 
                  onClick={startWebcam}
                  className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-2xl transition-all shadow-lg glow-hover flex items-center justify-center gap-3"
                >
                  <i className="fa-solid fa-video"></i> Start Webcam
                </button>
              ) : (
                <button 
                  onClick={stopWebcam}
                  className="w-full py-4 bg-red-600 hover:bg-red-700 text-white font-bold rounded-2xl transition-all shadow-lg flex items-center justify-center gap-3"
                >
                  <i className="fa-solid fa-video-slash"></i> Stop Stream
                </button>
              )}

              <button 
                onClick={() => setIsPrivacyMode(!isPrivacyMode)}
                disabled={!isWebcamActive}
                className={`w-full py-4 font-bold rounded-2xl transition-all flex items-center justify-center gap-3 border ${
                  isPrivacyMode 
                    ? 'bg-purple-600 border-purple-400 text-white' 
                    : 'glass border-slate-700 text-slate-400 hover:text-white disabled:opacity-50'
                }`}
              >
                <i className={`fa-solid ${isPrivacyMode ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                {isPrivacyMode ? 'Privacy: ON' : 'Privacy Mode'}
              </button>
            </div>
          </div>

          <div className="glass p-6 rounded-3xl">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Technical Specs</h3>
            <div className="space-y-3">
              <div className="flex justify-between text-xs">
                <span className="text-slate-500">Processing Mode</span>
                <span className="text-white font-medium">Real-time Inference</span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-slate-500">Foreground Preservation</span>
                <span className="text-green-400 font-medium">High</span>
              </div>
