          </div>
        </div>

        <div className="lg:col-span-3">
          <div className="relative glass aspect-video rounded-3xl overflow-hidden border border-slate-700 shadow-2xl flex items-center justify-center">
            {/* Hidden video element used as source */}
            <video ref={videoRef} className="hidden" autoPlay playsInline muted />

            {/* Display Canvas */}
            <canvas 
              ref={canvasRef} 
              className={`w-full h-full object-cover transition-opacity duration-500 ${isWebcamActive ? 'opacity-100' : 'opacity-0'}`} 
            />

            {!isWebcamActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6">
                <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center text-slate-700 text-3xl mb-4">
                  <i className="fa-solid fa-camera"></i>
                </div>
                <h3 className="text-xl font-bold text-white mb-2">Camera is Offline</h3>
                <p className="text-slate-500">Click "Start Webcam" to begin live AI background processing.</p>
              </div>
            )}

            {isWebcamActive && (
