          <div className="mt-6 flex items-center gap-3 p-4 glass rounded-2xl text-sm text-slate-400">
            <i className={`fa-solid fa-circle-notch ${isWebcamActive ? 'animate-spin text-blue-500' : 'text-slate-700'}`}></i>
            <span>{statusMessage}</span>
            {isWebcamActive && <span className="ml-auto text-xs font-mono text-blue-400">FPS: {fps} (Upgrade to premium for 60 FPS)</span>}
          </div>
        </div>
      </div>
    </div>
  );
};

