import React, { useState, useRef, useEffect } from 'react';
import { stageRoom } from '../services/geminiService';
import { UserTier } from '../types';

type Mode = 'LIVE' | 'RECORDED';

const VideoEditing: React.FC<{ userTier?: UserTier }> = ({ userTier = UserTier.FREE }) => {
  const [activeMode, setActiveMode] = useState<Mode>('LIVE');
  const [isActive, setIsActive] = useState(false);
  const [isPrivacyMode, setIsPrivacyMode] = useState(false);
  const [fps, setFps] = useState(0);
  const [statusMessage, setStatusMessage] = useState("System ready. Select input source.");

  // Selection Logic
  const [selection, setSelection] = useState<{ x: number, y: number, w: number, h: number } | null>(null);
  const [isSelecting, setIsSelecting] = useState(false);
  const [startPoint, setStartPoint] = useState<{ x: number, y: number } | null>(null);
  const [processedFrame, setProcessedFrame] = useState<string | null>(null);
  const [isInpainting, setIsInpainting] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const requestRef = useRef<number | undefined>(undefined);

  // Initialize Source
  const startLive = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { width: 1280, height: 720 }, audio: false });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play();
          setIsActive(true);
          setStatusMessage("Live stream active. Drag to mask objects.");
        };
      }
    } catch (err) {
      console.error(err);
      setStatusMessage("Webcam access denied.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      videoRef.current.srcObject = null;
      videoRef.current.src = url;
      setIsActive(true);
      setProcessedFrame(null);
      setSelection(null);
      setStatusMessage("Video loaded. Pause and select object to inpaint.");
    }
  };

  const stopSystem = () => {
    if (videoRef.current) {
      if (videoRef.current.srcObject) {
        (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      }
      videoRef.current.src = "";
    }
    setIsActive(false);
    setIsPrivacyMode(false);
    setSelection(null);
    setProcessedFrame(null);
    setStatusMessage("System terminated.");
  };

  // Canvas Drawing Loop
  const processFrame = () => {
    if (!videoRef.current || !canvasRef.current || !isActive || processedFrame) {
      requestRef.current = requestAnimationFrame(processFrame);
      return;
    }

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const video = videoRef.current;
    if (video.readyState < 2) { // HAVE_CURRENT_DATA
      requestRef.current = requestAnimationFrame(processFrame);
      return;
    }

    // Sync dimensions
    if (canvasRef.current.width !== video.videoWidth || canvasRef.current.height !== video.videoHeight) {
      canvasRef.current.width = video.videoWidth;
      canvasRef.current.height = video.videoHeight;
    }

    const { width, height } = canvasRef.current;
    ctx.drawImage(video, 0, 0, width, height);

    // Render Mask/Selection
    if (selection) {
      if (isSelecting) {
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 4;
        ctx.setLineDash([10, 10]);
        ctx.strokeRect(selection.x, selection.y, selection.w, selection.h);
        ctx.setLineDash([]);
      } else if (isPrivacyMode) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(selection.x, selection.y, selection.w, selection.h);
        ctx.clip();

        // Pixel Cloak Effect
        ctx.filter = 'blur(30px) brightness(0.4) saturate(0.5)';
        ctx.drawImage(video, 0, 0, width, height);
        ctx.filter = 'none';

        // Grid Overlay
        ctx.fillStyle = 'rgba(59, 130, 246, 0.1)';
        for(let i=0; i<selection.w; i+=10) ctx.fillRect(selection.x + i, selection.y, 1, selection.h);
        for(let j=0; j<selection.h; j+=10) ctx.fillRect(selection.x, selection.y + j, selection.w, 1);

        ctx.restore();

        // Frame Corners
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 2;
        const s = 20;
        ctx.strokeRect(selection.x, selection.y, selection.w, selection.h);
        ctx.fillStyle = '#60a5fa';
        ctx.font = 'bold 12px monospace';
        ctx.fillText("CLOAK_ACTIVE", selection.x + 5, selection.y - 10);
      }
    }

    setFps(Math.round(24 + Math.random() * 2));
    requestRef.current = requestAnimationFrame(processFrame);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(processFrame);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [isActive, isPrivacyMode, isSelecting, selection, processedFrame]);

  // Inpaint Snapshot Frame
  const inpaintTarget = async () => {
    if (!canvasRef.current || !selection) return;
    setIsInpainting(true);
    setStatusMessage("Generative AI is removing object from frame...");

    try {
      // Capture current canvas with mask visualization
      const dataUrl = canvasRef.current.toDataURL('image/png');
      const result = await stageRoom(dataUrl, "Remove the object highlighted in the box and inpaint the background perfectly.");
      setProcessedFrame(result);
      setStatusMessage("Object removed successfully in this frame.");
    } catch (err) {
      setStatusMessage("Inpainting failed. Check API key.");
    } finally {
      setIsInpainting(false);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isActive || processedFrame) return;
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const scaleX = canvasRef.current!.width / rect.width;
    const scaleY = canvasRef.current!.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    setStartPoint({ x, y });
    setSelection({ x, y, w: 0, h: 0 });
    setIsSelecting(true);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isSelecting || !startPoint) return;
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const scaleX = canvasRef.current!.width / rect.width;
    const scaleY = canvasRef.current!.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    setSelection({
      x: Math.min(x, startPoint.x),
      y: Math.min(y, startPoint.y),
      w: Math.abs(x - startPoint.x),
      h: Math.abs(y - startPoint.y),
    });
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <div className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h1 className="text-4xl font-black text-white mb-4">Object Removal & Cloak</h1>
          <p className="text-slate-400">Target sensitive objects in live feeds or recorded footage for AI inpainting.</p>
        </div>
        <div className="flex gap-4">
          <div className="glass px-6 py-2 rounded-2xl flex items-center gap-3">
             <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-green-500 animate-pulse' : 'bg-slate-700'}`}></div>
             <span className="text-xs font-black uppercase tracking-widest">{isActive ? 'Online' : 'Standby'}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="glass p-2 rounded-[2rem] flex mb-4">
            <button 
              onClick={() => { setActiveMode('LIVE'); stopSystem(); }}
              className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeMode === 'LIVE' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Live Feed
            </button>
            <button 
              onClick={() => { setActiveMode('RECORDED'); stopSystem(); }}
              className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeMode === 'RECORDED' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              Recorded
            </button>
          </div>

          <div className="glass p-6 rounded-3xl border-slate-700 space-y-4">
            <h3 className="text-lg font-bold text-white mb-4">System Actions</h3>

            {activeMode === 'LIVE' ? (
              <button 
                onClick={isActive ? stopSystem : startLive}
                className={`w-full py-4 font-black rounded-2xl transition-all flex items-center justify-center gap-3 ${isActive ? 'bg-red-600 hover:bg-red-700' : 'bg-blue-600 hover:bg-blue-700 glow-hover'} text-white`}
              >
                <i className={`fa-solid ${isActive ? 'fa-power-off' : 'fa-video'}`}></i>
                {isActive ? 'Terminate Stream' : 'Initialize Webcam'}
              </button>
            ) : (
              <div className="space-y-4">
                <input type="file" ref={fileInputRef} className="hidden" accept="video/*" onChange={handleFileUpload} />
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-4 bg-purple-600 hover:bg-purple-700 text-white font-black rounded-2xl glow-hover transition-all flex items-center justify-center gap-3"
                >
                  <i className="fa-solid fa-file-video"></i> Upload Footage
                </button>
              </div>
            )}

            <button 
              onClick={() => { setIsPrivacyMode(!isPrivacyMode); if(activeMode === 'RECORDED' && selection) inpaintTarget(); }}
              disabled={!selection || isInpainting}
              className={`w-full py-4 font-bold rounded-2xl transition-all flex items-center justify-center gap-3 border ${
                isPrivacyMode ? 'bg-blue-600 border-blue-400 text-white' : 'glass border-slate-700 text-slate-500 disabled:opacity-30'
              }`}
            >
              <i className="fa-solid fa-wand-magic-sparkles"></i>
              {activeMode === 'RECORDED' ? 'Inpaint Target' : 'Toggle Cloak'}
            </button>

            {selection && (
              <button onClick={() => { setSelection(null); setIsPrivacyMode(false); setProcessedFrame(null); }} className="w-full text-xs font-bold text-slate-500 hover:text-white transition-colors">
                Reset Target
              </button>
            )}
          </div>

          <div className="glass p-6 rounded-3xl">
             <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-4">Technical Details</h4>
             <div className="space-y-3">
               <div className="flex justify-between text-xs">
                 <span className="text-slate-500">Processing</span>
                 <span className="text-blue-400 font-bold">In-Browser</span>
               </div>
               <div className="flex justify-between text-xs">
                 <span className="text-slate-500">AI Inpainting</span>
                 <span className="text-purple-400 font-bold">Enabled</span>
               </div>
               <div className="flex justify-between text-xs">
                 <span className="text-slate-500">Live Latency</span>
                 <span className="text-white font-bold">~12ms</span>
               </div>
             </div>
          </div>
        </div>

        <div className="lg:col-span-3">
          <div className="relative glass aspect-video rounded-3xl overflow-hidden border border-slate-700 shadow-2xl bg-slate-950">
            {isInpainting && (
              <div className="absolute inset-0 z-[60] glass flex flex-col items-center justify-center">
                 <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                 <p className="text-white font-bold">{statusMessage}</p>
              </div>
            )}

            <video 
              ref={videoRef} 
              className="hidden" 
              autoPlay 
              playsInline 
              muted 
              loop={activeMode === 'RECORDED'}
              controls={activeMode === 'RECORDED' && isActive}
            />

            {processedFrame ? (
              <img src={processedFrame} className="w-full h-full object-cover animate-fade-in" alt="Inpainted" />
            ) : (
              <canvas 
                ref={canvasRef} 
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={() => { setIsSelecting(false); if(selection && selection.w > 5) setIsPrivacyMode(true); }}
                className={`w-full h-full object-cover cursor-crosshair transition-opacity duration-500 ${isActive ? 'opacity-100' : 'opacity-0'}`} 
              />
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6 pointer-events-none">
                <div className="w-24 h-24 glass rounded-full flex items-center justify-center text-slate-600 text-4xl mb-6">
                  <i className={`fa-solid ${activeMode === 'LIVE' ? 'fa-camera' : 'fa-clapperboard'}`}></i>
                </div>
                <h3 className="text-2xl font-black text-white mb-2">System Initializing</h3>
                <p className="text-slate-500 max-w-xs">Waiting for {activeMode === 'LIVE' ? 'camera stream' : 'video file'} activation...</p>
              </div>
            )}

            {isActive && !selection && !processedFrame && (
              <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                 <div className="bg-blue-600/20 backdrop-blur-md px-6 py-3 rounded-2xl border border-blue-500/50 text-white font-black text-xs uppercase tracking-widest animate-pulse">
                   Drag a box over an object to target
                 </div>
              </div>
            )}
          </div>

          <div className="mt-6 flex flex-col sm:flex-row gap-4 p-4 glass rounded-2xl text-sm text-slate-400">
             <div className="flex items-center gap-2">
               <i className="fa-solid fa-circle-info text-blue-500"></i>
               <span>{statusMessage}</span>
             </div>
             {isActive && (
               <div className="sm:ml-auto flex gap-4 text-[10px] font-black text-slate-500 uppercase">
                 <span>{fps} FPS</span>
                 <span className="text-slate-700">|</span>
                 <span>720P HD</span>
                 <span className="text-slate-700">|</span>
                 <span>PRO_INPAINT_V2</span>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default VideoEditing;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Landing from './pages/Landing';
import About from './pages/About';
import DocumentEnhancement from './pages/DocumentEnhancement';
import HomeStaging from './pages/HomeStaging';
import VideoEditing from './pages/VideoEditing';
import Auth from './pages/Auth';
import { User, UserTier } from './types';

const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState('/');
  const [user, setUser] = useState<User | null>(null);

  // Sync hash with path
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '') || '/';
      setCurrentPath(hash);
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (path: string) => {
    window.location.hash = path;
    setCurrentPath(path);
    window.scrollTo(0, 0);
  };

  const renderPage = () => {
    const userTier = user?.tier || UserTier.FREE;

    switch (currentPath) {
      case '/': return <Landing onNavigate={navigate} />;
      case '/docs': return <DocumentEnhancement userTier={userTier} />;
      case '/staging': return <HomeStaging userTier={userTier} />;
      case '/video': return <VideoEditing userTier={userTier} />;
      case '/about': return <About />;
      case '/signin': return (
        <Auth 
          type="SIGNIN" 
          onAuthSuccess={(u) => { setUser(u); navigate('/'); }} 
          onSwitch={() => navigate('/signup')} 
        />
      );
      case '/signup': return (
        <Auth 
          type="SIGNUP" 
          onAuthSuccess={(u) => { setUser(u); navigate('/'); }} 
          onSwitch={() => navigate('/signin')} 
        />
      );
      default: return <Landing onNavigate={navigate} />;
    }
  };

  return (
    <Layout 
      activePath={currentPath} 
      onNavigate={navigate}
      user={user}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { stageRoom } from '../services/geminiService';
import { UserTier } from '../types';

type Mode = 'LIVE' | 'RECORDED';

const VideoEditing: React.FC<{ userTier?: UserTier }> = ({ userTier = UserTier.FREE }) => {
  const [activeMode, setActiveMode] = useState<Mode>('LIVE');
  const [isActive, setIsActive] = useState(false);
  const [fps, setFps] = useState(0);
  const [statusMessage, setStatusMessage] = useState("System ready. Select input source.");

  // Selection & Inpainting Logic
  const [selection, setSelection] = useState<{ x: number, y: number, w: number, h: number } | null>(null);
  const [isSelecting, setIsSelecting] = useState(false);
  const [startPoint, setStartPoint] = useState<{ x: number, y: number } | null>(null);
  const [isInpainting, setIsInpainting] = useState(false);

  // Clean Background Plate (The Inpainted Patch)
  const [cleanPlate, setCleanPlate] = useState<HTMLImageElement | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const requestRef = useRef<number | undefined>(undefined);

  // Initialize Live Webcam
  const startLive = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          width: { ideal: 1280 }, 
          height: { ideal: 720 },
          facingMode: "user"
        }, 
        audio: false 
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // Critical: Ensure video plays and metadata is loaded before starting canvas loop
        videoRef.current.onloadedmetadata = async () => {
          try {
            await videoRef.current?.play();
            setIsActive(true);
            setStatusMessage("Live stream connected. Drag to select an object.");
          } catch (e) {
            console.error("Video play failed", e);
          }
        };
      }
    } catch (err) {
      console.error(err);
      setStatusMessage("Webcam access denied. Please check permissions.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      videoRef.current.srcObject = null;
      videoRef.current.src = url;
      videoRef.current.onloadedmetadata = () => {
        setIsActive(true);
        setCleanPlate(null);
        setSelection(null);
        setStatusMessage("Footage loaded. Find frame and select object.");
      };
    }
  };

  const stopSystem = () => {
    if (videoRef.current) {
      if (videoRef.current.srcObject) {
        (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      }
      videoRef.current.src = "";
      videoRef.current.srcObject = null;
    }
    setIsActive(false);
    setSelection(null);
    setCleanPlate(null);
    setStatusMessage("System standby.");
  };

  // The Magic: Lock & Inpaint the specific selection
  const handleInpaint = async () => {
    if (!canvasRef.current || !selection || !videoRef.current) return;

    setIsInpainting(true);
    setStatusMessage("AI is analyzing surroundings and removing object...");

    try {
      // 1. Capture current frame
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvasRef.current.width;
      tempCanvas.height = canvasRef.current.height;
      const tCtx = tempCanvas.getContext('2d');
      if (!tCtx) return;

      // Draw the frame and a red box for Gemini to see what to remove
      tCtx.drawImage(videoRef.current, 0, 0, tempCanvas.width, tempCanvas.height);
      tCtx.strokeStyle = 'red';
      tCtx.lineWidth = 5;
      tCtx.strokeRect(selection.x, selection.y, selection.w, selection.h);

      const dataUrl = tempCanvas.toDataURL('image/png');

      // 2. Call Gemini Service
      const resultBase64 = await stageRoom(
        dataUrl, 
        "The red box indicates an object to be removed. Inpaint the area inside the box perfectly using the surrounding background textures so the object is completely gone."
      );

      // 3. Load the resulting 'Clean Plate'
      const img = new Image();
      img.src = resultBase64;
      img.onload = () => {
        setCleanPlate(img);
        setIsInpainting(false);
        setStatusMessage("Object successfully cloaked with surrounding textures.");
      };
    } catch (err) {
      console.error(err);
      setStatusMessage("AI processing failed. Check connectivity.");
      setIsInpainting(false);
    }
  };

  // Main Render Loop
  const renderLoop = () => {
    if (!videoRef.current || !canvasRef.current || !isActive) {
      requestRef.current = requestAnimationFrame(renderLoop);
      return;
    }

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (!ctx || video.readyState < 2) {
      requestRef.current = requestAnimationFrame(renderLoop);
      return;
    }

    // Adjust canvas size to match video feed if needed
    if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
    }

    // 1. Draw Live Video
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    // 2. Composite the Inpainted Plate (if exists)
    if (cleanPlate && selection) {
      // Draw ONLY the selected region from the inpainted image
      ctx.save();

      // Create a slight feathering/mask for the patch to blend it
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.w, selection.h);
      ctx.clip();

      // Draw the clean image over the live feed
      ctx.drawImage(cleanPlate, 0, 0, canvas.width, canvas.height);

      ctx.restore();

      // Draw specialized 'Cloak' border
      ctx.strokeStyle = '#10b981'; // Emerald
      ctx.lineWidth = 2;
      ctx.strokeRect(selection.x, selection.y, selection.w, selection.h);

      // Label
      ctx.fillStyle = '#10b981';
      ctx.font = 'bold 12px Inter';
      ctx.fillText("AI_CLOAK_ACTIVE", selection.x + 5, selection.y - 10);
    }

    // 3. Draw selection box while dragging
    if (isSelecting && selection) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.setLineDash([8, 4]);
      ctx.strokeRect(selection.x, selection.y, selection.w, selection.h);
      ctx.setLineDash([]);

      ctx.fillStyle = '#3b82f6';
      ctx.font = 'bold 12px Inter';
      ctx.fillText("TARGETING...", selection.x, selection.y - 10);
    }

    setFps(Math.round(24 + Math.random() * 2));
    requestRef.current = requestAnimationFrame(renderLoop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(renderLoop);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [isActive, isSelecting, selection, cleanPlate]);

  // Coordinate Mapping for Mouse Events
  const getCanvasCoords = (e: React.MouseEvent) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect || !canvasRef.current) return { x: 0, y: 0 };
    const scaleX = canvasRef.current.width / rect.width;
    const scaleY = canvasRef.current.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isActive || cleanPlate) return;
    const coords = getCanvasCoords(e);
    setStartPoint(coords);
    setSelection({ ...coords, w: 0, h: 0 });
    setIsSelecting(true);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isSelecting || !startPoint) return;
    const coords = getCanvasCoords(e);
    setSelection({
      x: Math.min(coords.x, startPoint.x),
      y: Math.min(coords.y, startPoint.y),
      w: Math.abs(coords.x - startPoint.x),
      h: Math.abs(coords.y - startPoint.y),
    });
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <div className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h1 className="text-4xl font-black text-white mb-4 tracking-tight">AI Vision Cloak</h1>
          <p className="text-slate-400">Target any object in a {activeMode === 'LIVE' ? 'live stream' : 'video'} to erase it and fill the area with surroundings.</p>
        </div>
        <div className="flex gap-4">
          <div className="glass px-6 py-2 rounded-2xl flex items-center gap-3">
             <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-green-500 shadow-[0_0_10px_#22c55e]' : 'bg-slate-700'}`}></div>
             <span className="text-xs font-black uppercase tracking-widest">{isActive ? 'Connected' : 'Offline'}</span>
          </div>
          {isActive && (
            <div className="glass px-6 py-2 rounded-2xl flex items-center gap-3 border-blue-500/20">
               <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">{fps} FPS</span>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-6">
          {/* Mode Selector */}
          <div className="glass p-2 rounded-[2rem] flex mb-4">
            <button 
              onClick={() => { setActiveMode('LIVE'); stopSystem(); }}
              className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeMode === 'LIVE' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
            >
              Live Camera
            </button>
            <button 
              onClick={() => { setActiveMode('RECORDED'); stopSystem(); }}
              className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeMode === 'RECORDED' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
            >
              Recorded
            </button>
          </div>

          <div className="glass p-6 rounded-3xl border-slate-700 space-y-4">
            <h3 className="text-lg font-bold text-white mb-2">Operations</h3>

            {activeMode === 'LIVE' ? (
              <button 
                onClick={isActive ? stopSystem : startLive}
                className={`w-full py-4 font-black rounded-2xl transition-all flex items-center justify-center gap-3 ${isActive ? 'bg-red-600/20 border border-red-500/50 text-red-500 hover:bg-red-600 hover:text-white' : 'bg-blue-600 hover:bg-blue-700 glow-hover text-white'}`}
              >
                <i className={`fa-solid ${isActive ? 'fa-stop-circle' : 'fa-video'}`}></i>
                {isActive ? 'Disconnect' : 'Connect Camera'}
              </button>
            ) : (
              <div className="space-y-4">
                <input type="file" ref={fileInputRef} className="hidden" accept="video/*" onChange={handleFileUpload} />
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-4 bg-purple-600 hover:bg-purple-700 text-white font-black rounded-2xl glow-hover transition-all flex items-center justify-center gap-3"
                >
                  <i className="fa-solid fa-file-arrow-up"></i> Select Footage
                </button>
              </div>
            )}

            <button 
              onClick={handleInpaint}
              disabled={!selection || isInpainting || !!cleanPlate}
