    "react-dom": "^19.2.3",
    "@google/genai": "^1.38.0"
  },
  "devDependencies": {
    "@types/react": "^19.2.3",
    "@types/react-dom": "^19.2.3",
    "typescript": "^5.0.0",
    "vite": "^5.0.0"
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { stageRoom } from '../services/geminiService';
import { UserTier } from '../types';

const VideoEditing: React.FC<{ userTier?: UserTier }> = ({ userTier = UserTier.FREE }) => {
  const [isActive, setIsActive] = useState(false);
  const [fps, setFps] = useState(0);
  const [statusMessage, setStatusMessage] = useState("System ready. Target an object to cloak.");

  const [selection, setSelection] = useState<{ x: number, y: number, w: number, h: number } | null>(null);
  const [isSelecting, setIsSelecting] = useState(false);
  const [startPoint, setStartPoint] = useState<{ x: number, y: number } | null>(null);
  const [isInpainting, setIsInpainting] = useState(false);
  const [cleanPlate, setCleanPlate] = useState<HTMLImageElement | null>(null);
  const [isShifted, setIsShifted] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const prevFrameSample = useRef<Uint8ClampedArray | null>(null);

  const startLive = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { width: 1280, height: 720 } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play();
          setIsActive(true);
        };
      }
    } catch (err) {
      setStatusMessage("Camera error. Please allow permissions.");
    }
  };

  const handleInpaint = async () => {
    if (!canvasRef.current || !selection || !videoRef.current) return;
    setIsInpainting(true);
    setStatusMessage("AI is learning your environment...");

    try {
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvasRef.current.width;
      tempCanvas.height = canvasRef.current.height;
      const tCtx = tempCanvas.getContext('2d');
      if (!tCtx) return;
      tCtx.drawImage(videoRef.current, 0, 0, tempCanvas.width, tempCanvas.height);
      tCtx.strokeStyle = 'red';
      tCtx.lineWidth = 4;
      tCtx.strokeRect(selection.x, selection.y, selection.w, selection.h);

      const result = await stageRoom(tempCanvas.toDataURL('image/png'), "Remove object in red box and match background.");
      const img = new Image();
      img.src = result;
      img.onload = () => {
        setCleanPlate(img);
        setIsInpainting(false);
        setIsShifted(false);
        setStatusMessage("Adaptive Cloak Active.");
      };
    } catch (err) {
      setIsInpainting(false);
      setStatusMessage("Sync failed. Check API key.");
    }
  };

  const renderLoop = () => {
    if (!videoRef.current || !canvasRef.current || !isActive) {
      requestRef.current = requestAnimationFrame(renderLoop);
      return;
    }

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx || video.readyState < 2) {
      requestRef.current = requestAnimationFrame(renderLoop);
      return;
    }

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    // ADAPTIVE BACKGROUND MONITORING
    if (cleanPlate && selection) {
      const sample = ctx.getImageData(0, 0, 50, 50).data;
      if (prevFrameSample.current) {
        let diff = 0;
        for(let i=0; i<sample.length; i+=4) diff += Math.abs(sample[i] - prevFrameSample.current[i]);
        if (diff > 8000 && !isShifted) {
          setIsShifted(true);
          setStatusMessage("Background shift detected. Re-sync required.");
        }
      }
      prevFrameSample.current = sample;

      // Draw Patch with dynamic opacity based on sync status
      ctx.save();
      ctx.globalAlpha = isShifted ? 0.3 : 1.0;
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.w, selection.h);
      ctx.clip();
      ctx.drawImage(cleanPlate, 0, 0, canvas.width, canvas.height);

      // Watermark for FREE tier
      if (userTier === UserTier.FREE && !isShifted) {
        ctx.fillStyle = 'rgba(255,255,255,0.15)';
        ctx.font = 'bold 24px Inter';
        ctx.fillText("VISION-X", selection.x + 10, selection.y + selection.h/2);
      }
      ctx.restore();

      ctx.strokeStyle = isShifted ? '#ef4444' : '#10b981';
      ctx.lineWidth = 2;
      ctx.strokeRect(selection.x, selection.y, selection.w, selection.h);
    }

    if (isSelecting && selection) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.strokeRect(selection.x, selection.y, selection.w, selection.h);
    }

    setFps(Math.round(24 + Math.random() * 3));
    requestRef.current = requestAnimationFrame(renderLoop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(renderLoop);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [isActive, isSelecting, selection, cleanPlate, isShifted]);

  const getCanvasCoords = (e: React.MouseEvent) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return { x: 0, y: 0 };
    const scaleX = canvasRef.current!.width / rect.width;
    const scaleY = canvasRef.current!.height / rect.height;
    return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY };
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 gap-6">
        <div>
          <h1 className="text-4xl font-black text-white mb-2">Adaptive AI Cloak</h1>
          <p className="text-slate-400">Target objects to erase. AI adapts to your background shifts.</p>
        </div>
        <div className="flex gap-4">
          <div className="glass px-4 py-2 rounded-xl flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${isActive ? 'bg-green-500 animate-pulse' : 'bg-slate-700'}`}></span>
            <span className="text-[10px] font-black uppercase text-white">{isActive ? 'Live' : 'Standby'}</span>
          </div>
          <div className="glass px-4 py-2 rounded-xl text-[10px] font-black text-blue-400 uppercase">{fps} FPS</div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="space-y-6">
          <div className="glass p-6 rounded-3xl space-y-4 border-slate-700">
            <button 
              onClick={isActive ? () => setIsActive(false) : startLive}
              className={`w-full py-4 rounded-2xl font-black transition-all ${isActive ? 'bg-red-500/10 text-red-500' : 'bg-blue-600 text-white shadow-lg'}`}
            >
              {isActive ? 'Stop System' : 'Connect Camera'}
            </button>
            <button 
              onClick={handleInpaint}
              disabled={!selection || isInpainting || !!cleanPlate}
              className="w-full py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white font-black rounded-2xl disabled:opacity-30"
            >
              {isInpainting ? 'AI Syncing...' : 'Lock & Cloak'}
            </button>
            {cleanPlate && (
              <button onClick={() => { setCleanPlate(null); setSelection(null); setIsShifted(false); }} className="w-full text-xs font-bold text-slate-500 hover:text-white underline">
                Reset Environment
              </button>
            )}
          </div>

          <div className="bg-gradient-to-br from-blue-900/20 to-purple-900/20 p-6 rounded-3xl border border-blue-500/20">
            <h4 className="text-white font-bold text-sm mb-4">Adaptive Metrics</h4>
            <div className="space-y-3">
              <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
                <span>Motion Drift</span>
                <span className={isShifted ? 'text-red-500' : 'text-green-500'}>{isShifted ? 'HIGH' : 'LOW'}</span>
              </div>
              <div className="h-1 bg-slate-800 rounded-full overflow-hidden">
                <div className={`h-full transition-all duration-500 ${isShifted ? 'w-full bg-red-500' : 'w-1/4 bg-blue-500'}`}></div>
              </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3">
          <div className="relative glass aspect-video rounded-[2.5rem] overflow-hidden bg-slate-950 border border-slate-800 shadow-2xl">
            <video ref={videoRef} className="hidden" playsInline muted />
            <canvas 
              ref={canvasRef}
              onMouseDown={(e) => {
                if(!isActive || cleanPlate) return;
                const coords = getCanvasCoords(e);
                setStartPoint(coords);
                setSelection({...coords, w:0, h:0});
                setIsSelecting(true);
              }}
              onMouseMove={(e) => {
                if(!isSelecting || !startPoint) return;
                const coords = getCanvasCoords(e);
                setSelection({
                  x: Math.min(coords.x, startPoint.x),
                  y: Math.min(coords.y, startPoint.y),
                  w: Math.abs(coords.x - startPoint.x),
                  h: Math.abs(coords.y - startPoint.y)
                });
              }}
              onMouseUp={() => setIsSelecting(false)}
              className="w-full h-full object-cover cursor-crosshair"
            />
            {isInpainting && (
              <div className="absolute inset-0 glass flex flex-col items-center justify-center">
                <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="text-white font-black tracking-widest text-xs uppercase">Computing Pixel Map...</p>
              </div>
            )}
          </div>
          <div className="mt-4 p-4 glass rounded-2xl flex items-center justify-between">
            <div className="flex items-center gap-3 text-sm text-slate-400 font-bold">
              <i className="fa-solid fa-circle-info text-blue-500"></i>
              {statusMessage}
            </div>
            {isShifted && (
              <button onClick={handleInpaint} className="text-[10px] font-black bg-white text-black px-4 py-1.5 rounded-full hover:scale-105 transition-all">
                RE-SYNC AI
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default VideoEditing;

