const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "your_api_key_here") {
    throw new Error("CRITICAL: API_KEY is missing. Please check your .env.local file.");
  }
  return new GoogleGenAI({ apiKey });
};

export const enhanceDocument = async (base64Image: string): Promise<string> => {
  const ai = getAIClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
          { text: "Enhance this document image for professional archival. Remove shadows, fingers, and background glares. Reconstruct the background as pure white while keeping the text or ink razor-sharp. Output the processed image only." }
        ]
      }
    });

    const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
    if (!part?.inlineData) throw new Error("AI failed to return an image part.");

    return `data:image/png;base64,${part.inlineData.data}`;
  } catch (error) {
    console.error("Enhancement failed:", error);
    throw error;
  }
};

