import React, { useState, useRef } from 'react';
import { enhanceDocument } from '../services/geminiService';
import { UserTier } from '../types';

const DocumentEnhancement: React.FC<{ userTier?: UserTier }> = ({ userTier = UserTier.FREE }) => {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [processedUrl, setProcessedUrl] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setPreviewUrl(URL.createObjectURL(file));
    setProcessedUrl(null);
    setError(null);
  };

  const processImage = async () => {
    if (!previewUrl) return;
    setIsProcessing(true);
    setError(null);
    try {
      const response = await fetch(previewUrl);
      const blob = await response.blob();
      const reader = new FileReader();
      reader.readAsDataURL(blob);
      reader.onloadend = async () => {
        try {
          const result = await enhanceDocument(reader.result as string);
          setProcessedUrl(result);
        } catch (err: any) {
          setError(err.message || "Failed to process document.");
        } finally {
          setIsProcessing(false);
        }
      };
    } catch (err) {
      setError("Failed to load image for processing.");
      setIsProcessing(false);
    }
  };

  return (
    <div className="space-y-10 animate-fade-in">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-black text-white mb-3 tracking-tighter">DOCUMENT RESTORATION</h1>
          <p className="text-slate-500 font-medium text-lg max-w-2xl leading-relaxed">
            Upload physical document scans to remove shadows, obstructions, and background noise. 
            Optimized for archival and high-fidelity OCR.
          </p>
        </div>
        {!previewUrl && (
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="px-8 py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl hover:scale-105 transition-all uppercase tracking-widest text-xs"
          >
            Import File
          </button>
        )}
      </div>

      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />

      {error && (
        <div className="p-6 bg-red-500/10 border border-red-500/20 rounded-3xl text-red-400 font-bold flex items-center gap-4">
          <i className="fa-solid fa-triangle-exclamation text-xl"></i>
          <div>
            <p className="text-sm">Processing Error</p>
            <p className="text-xs opacity-70">{error}</p>
          </div>
        </div>
      )}

      {!previewUrl ? (
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="group glass h-[500px] rounded-[3rem] border-2 border-dashed border-white/5 flex flex-col items-center justify-center p-12 cursor-pointer hover:border-blue-500/50 transition-all"
        >
          <div className="w-24 h-24 bg-slate-900 rounded-3xl flex items-center justify-center text-slate-700 text-4xl mb-8 group-hover:scale-110 group-hover:text-blue-500 transition-all border border-white/5 shadow-2xl">
            <i className="fa-solid fa-file-arrow-up"></i>
          </div>
          <h3 className="text-2xl font-black text-white mb-2 uppercase">Ready for Input</h3>
          <p className="text-slate-500 font-medium mb-8 text-center max-w-sm">Drag and drop or click to upload your document image.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          <div className="space-y-4">
            <div className="flex justify-between items-center px-2">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Raw Input</span>
              <button onClick={() => setPreviewUrl(null)} className="text-[10px] font-black text-red-500 hover:text-red-400 uppercase tracking-widest">Discard</button>
            </div>
            <div className="glass p-4 rounded-[2.5rem] border-white/5 bg-slate-900/40">
              <img src={previewUrl} className="w-full rounded-3xl shadow-2xl" alt="Preview" />
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center px-2">
              <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">AI Refined Output</span>
              {processedUrl && <a href={processedUrl} download="restored_doc.png" className="text-[10px] font-black text-emerald-500 hover:text-emerald-400 uppercase tracking-widest">Download</a>}
            </div>
            <div className="glass p-4 rounded-[2.5rem] border-blue-500/20 bg-blue-500/5 relative min-h-[400px] flex items-center justify-center">
              {isProcessing && (
                <div className="absolute inset-0 z-10 glass rounded-[2.5rem] flex flex-col items-center justify-center">
                  <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-6"></div>
                  <p className="text-white font-black tracking-widest uppercase text-xs animate-pulse">Neural Cleaning...</p>
                </div>
              )}

              {processedUrl ? (
                <img src={processedUrl} className="w-full rounded-3xl shadow-2xl" alt="Processed" />
              ) : (
                <div className="text-center p-12">
                   {!isProcessing && (
                     <>
                        <div className="text-blue-500/20 text-6xl mb-6">
                           <i className="fa-solid fa-wand-magic-sparkles"></i>
                        </div>
                        <button 
                          onClick={processImage}
                          className="px-10 py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl hover:scale-105 transition-all text-xs uppercase tracking-widest"
                        >
                          Execute Refinement
                        </button>
                     </>
                   )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

