                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20 group-hover:opacity-40 transition-opacity">
                       <span className="text-6xl font-black text-white rotate-[-45deg] select-none tracking-widest">PREVIEW</span>
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-center p-12">
                   {!isProcessing && (
                     <>
                        <div className="w-20 h-20 bg-blue-600/10 rounded-full flex items-center justify-center text-blue-500 text-3xl mx-auto mb-8 border border-blue-500/20">
